def blog(lang, G):
    """build.py sayfa üreticisi: G, build.py'nin globals() sözlüğüdür."""
    t = lambda tr, en: tr if lang == "tr" else en
    layout, NAME, page_url, abs_img, person_ld, crumbs, SITE_URL, IMG = (G[k] for k in ("layout", "NAME", "page_url", "abs_img", "person_ld", "crumbs", "SITE_URL", "IMG"))
    posts = build_posts(lang, IMG)
    arts = ""
    for p in posts:
        tags = p["tags"] if lang == "tr" else p["tags_en"]
        arts += f"""<article class="post wrap" id="{p['id']}" itemscope itemtype="https://schema.org/BlogPosting">
  <div class="post-aside"><p class="post-meta"><time datetime="{p['date']}" itemprop="datePublished">{p['date']}</time><br>{p['mins']} {t("dk okuma", "min read")}<br>{", ".join(tags)}</p></div>
  <div><h2 itemprop="headline">{p['title']}</h2><p class="lead" itemprop="description" style="margin-top:1rem">{p['intro']}</p><div class="post-body" itemprop="articleBody">{p['body']}</div></div>
</article>"""
    toc = "".join(f'<li><a href="#{p["id"]}">{p["title"]}</a></li>' for p in posts)
    body = f"""
<div class="wrap page-head">
  <h1>Blog</h1>
  <p>{t("Yaptığım işlerden çıkardığım üç yazı: yapay zekâ ile 3B site, backend'siz iletişim formu ve Photoshop'ta web arayüzü.", "Three posts from things I built: a 3D site with AI, a form with no backend and a web interface in Photoshop.")}</p>
  <ul class="toc">{toc}</ul>
</div>
{arts}
"""
    title = t(f"Blog | {NAME}: Yapay Zekâ, İletişim Formu ve Photoshop", f"Blog | {NAME}: AI, Contact Form and Photoshop UI")
    desc = t("Yapay zekâ ile 3B site yapımı, backend'siz çalışan iletişim formu ve Photoshop ile web arayüzü tasarımı üzerine ekran görüntülü üç yazı.",
             "Three posts with screenshots on building a 3D site with AI, a contact form that needs no backend and designing a web interface in Photoshop.")
    ld = [{"@context": "https://schema.org", "@type": "Blog", "name": f"{NAME} Blog", "url": page_url(lang, "blog"), "inLanguage": lang,
           "blogPost": [{"@type": "BlogPosting", "headline": p["title"], "description": p["intro"], "datePublished": p["date"],
                         "url": page_url(lang, "blog") + "#" + p["id"], "inLanguage": lang, "image": abs_img("blog/" + p["image"]),
                         "author": {"@id": f"{SITE_URL}/#person"}} for p in posts]},
          person_ld(lang), crumbs(lang, "blog")]
    return layout(lang, "blog", title, desc, body, ld)
